window.RI2_UNITS = {"1":{"unit":1,"code":"RI2-U01","title":"FOOD & HEALTH","startNumber":1,"endNumber":33,"entries":[{"number":1,"term":"leave sb doing sth","sourceTerm":"leave (v) sb doing sth","spoken":"leave somebody doing something","ipa":"leave /liːv/","type":"verb · phrase / pattern","meaning":"khiến cho ai đó làm gì…","definition":"To cause someone to remain in a particular activity or situation.","note":"Leave sb doing sth nhấn mạnh người đó tiếp tục ở trong tình trạng hoặc hoạt động ấy.","example":"The sudden shortage left many families searching for enough food."},{"number":2,"term":"in this way # by the way","sourceTerm":"in this way # by the way","spoken":"in this way , by the way","ipa":"this /ðɪs/ · way /weɪ/","type":"adverb · adverb · phrase / pattern","meaning":"theo cách này · nhân tiện, tiện thể","definition":"By using the method or action that has just been described.","note":"In this way mang nghĩa “theo cách này”. By the way dùng để chuyển sang một ý phụ, không thay thế cho in this way.","example":"Farmers can store grain in sealed containers; in this way, they protect it from insects."},{"number":3,"term":"trace · trace a path","sourceTerm":"trace · trace a path","spoken":"trace , trace a path","ipa":"trace /treɪs/ · path /pæθ/","type":"verb · verb","meaning":"lần theo, truy tìm · lần theo đường đi hoặc lộ trình","definition":"To follow the course, development, or origin of something.","note":"Trace a path/route/origin lần lượt mang nghĩa lần theo đường đi, lộ trình hoặc nguồn gốc.","example":"Researchers traced the crop disease along the route used to transport seeds."},{"number":4,"term":"culprit","sourceTerm":"culprit (n)","spoken":"culprit","ipa":"culprit /ˈkʌlprɪt/","type":"noun","meaning":"thủ phạm, nguyên nhân","definition":"A person or thing responsible for a crime, problem, or harmful result.","note":"Culprit có thể chỉ người gây ra việc xấu hoặc nguyên nhân gây ra một vấn đề.","example":"Poor storage, rather than low production, was the main culprit behind the food loss."},{"number":5,"term":"major · the majority of","sourceTerm":"major · the majority of","spoken":"major , the majority of","ipa":"major /ˈmeɪdʒɚ/ · majority /məˈdʒɔːrəti/","type":"noun · adjective","meaning":"chính, quan trọng, chủ yếu · phần lớn, đa số","definition":"Major means important or large in effect; the majority of means most of a group.","note":"Major + danh từ. The majority of + danh từ số nhiều thường đi với động từ số nhiều.","example":"Drought is a major threat because the majority of local farms depend on rainfall."},{"number":6,"term":"efficient ~ effective","sourceTerm":"efficient ~ effective","spoken":"efficient , effective","ipa":"efficient /ɪˈfɪʃənt/ · effective /ɪˈfɛktɪv/","type":"adjective · adjective","meaning":"hiệu quả vì ít tốn thời gian hoặc nguồn lực ~ hiệu quả vì đạt kết quả mong muốn","definition":"Efficient uses time or resources well; effective produces the intended result.","note":"Efficient nhấn mạnh ít lãng phí. Effective nhấn mạnh đạt được kết quả mong muốn.","example":"The new system is efficient because it uses less water, and it is effective at protecting crops."},{"number":7,"term":"obvious","sourceTerm":"obvious (a)","spoken":"obvious","ipa":"obvious /ˈɑːbviəs/","type":"adjective","meaning":"hiển nhiên, rõ ràng","definition":"Easy to notice, recognize, or understand.","note":"","example":"It soon became obvious that the damaged wheat could not be sold."},{"number":8,"term":"cereal # wheat","sourceTerm":"cereal # wheat","spoken":"cereal , wheat","ipa":"cereal /ˈsɪriəl/ · wheat /wiːt/","type":"noun · noun","meaning":"ngũ cốc, thực phẩm làm từ ngũ cốc · lúa mì","definition":"A cereal is a grain crop or food made from grain; wheat is one particular cereal crop.","note":"Cereal là nhóm ngũ cốc nói chung. Wheat chỉ riêng lúa mì.","example":"Wheat is the main cereal grown in this dry region."},{"number":9,"term":"facility","sourceTerm":"facility (n)","spoken":"facility","ipa":"facility /fəˈsɪlɪti/","type":"noun","meaning":"cơ sở vật chất","definition":"A building, place, or set of equipment provided for a particular purpose.","note":"Facility thường chỉ một cơ sở cụ thể. Facilities ở số nhiều còn có thể chỉ các tiện nghi hoặc thiết bị.","example":"The research facility tests the nutritional quality of new crop varieties."},{"number":10,"term":"raw · raw material","sourceTerm":"raw · raw material","spoken":"raw , raw material","ipa":"raw /rɑː/ · material /məˈtɪriəl/","type":"noun · adjective","meaning":"sống, chưa chế biến; thô · nguyên liệu thô, nguyên liệu đầu vào","definition":"Raw means not yet cooked or processed; a raw material is a basic substance used to make a product.","note":"Raw food chỉ thực phẩm sống hoặc chưa chế biến. Raw material chỉ nguyên liệu đầu vào.","example":"The factory turns raw wheat into flour, its main raw material for bread."},{"number":11,"term":"deadly # dead","sourceTerm":"deadly # dead","spoken":"deadly , dead","ipa":"deadly /ˈdɛdli/ · dead /dɛd/","type":"adjective · adjective","meaning":"có thể gây chết người · đã chết, không còn sống","definition":"Deadly means able or likely to cause death; dead means no longer alive.","note":"Deadly mô tả thứ có thể gây chết người hoặc sinh vật. Dead mô tả trạng thái đã chết.","example":"The deadly plant disease spread quickly and left many young plants dead."},{"number":12,"term":"crop","sourceTerm":"crop (n)","spoken":"crop","ipa":"crop /krɑːp/","type":"noun","meaning":"vụ mùa, mùa màng","definition":"A plant grown in large quantities for food or another useful product.","note":"Crop có thể chỉ loại cây trồng hoặc lượng nông sản thu được trong một mùa.","example":"Farmers changed the planting date to protect the rice crop from flooding."},{"number":13,"term":"solely ~ only","sourceTerm":"solely (adv) ~ only (adv)","spoken":"solely , only","ipa":"solely /ˈsoʊəli/ · only /ˈoʊnli/","type":"adverb · adverb","meaning":"chỉ, duy nhất","definition":"Only and not involving anyone or anything else.","note":"Solely trang trọng hơn only và thường đứng trước phần được nhấn mạnh.","example":"Food security cannot depend solely on increasing production."},{"number":14,"term":"famine","sourceTerm":"famine (n)","spoken":"famine","ipa":"famine /ˈfæmən/","type":"noun","meaning":"nạn đói","definition":"An extreme and prolonged shortage of food affecting many people.","note":"Famine chỉ tình trạng thiếu lương thực nghiêm trọng trên diện rộng và kéo dài.","example":"Years of crop failure caused a severe famine across the region."},{"number":15,"term":"on a/an ... scale","sourceTerm":"on a/an ... scale (prep)","spoken":"on a or an ... scale","ipa":"scale /skeɪl/","type":"preposition","meaning":"trên quy mô…","definition":"At a particular level of size, extent, or importance.","note":"Các kết hợp thường gặp: on a large/small/global/national scale.","example":"The loss of crops occurred on a national scale after the drought."},{"number":16,"term":"quality","sourceTerm":"quality (n)","spoken":"quality","ipa":"quality /ˈkwɑːləti/","type":"noun","meaning":"chất lượng · phẩm chất, đặc tính","definition":"The standard of something, or a characteristic that a person or thing has.","note":"Quality là chất lượng khi nói về tiêu chuẩn. A quality là một phẩm chất hoặc đặc tính.","example":"The laboratory checks seed quality and identifies qualities that help plants survive heat."},{"number":17,"term":"seed","sourceTerm":"seed (n)","spoken":"seed","ipa":"seed /siːd/","type":"noun","meaning":"hạt giống","definition":"The small part of a plant from which a new plant can grow.","note":"","example":"Scientists selected seeds that could grow with less water."},{"number":18,"term":"continent","sourceTerm":"continent (n)","spoken":"continent","ipa":"continent /ˈkɑːntənənt/","type":"noun","meaning":"lục địa, châu lục","definition":"One of the Earth's seven large continuous areas of land.","note":"","example":"The crop is now grown on every inhabited continent."},{"number":19,"term":"trade","sourceTerm":"trade (v) · (n)","spoken":"trade","ipa":"trade /treɪd/","type":"verb · noun","meaning":"buôn bán, giao thương · thương mại","definition":"To buy, sell, or exchange goods; also the activity of doing this.","note":"Trade in + mặt hàng. Trade with + người, tổ chức hoặc quốc gia.","example":"Coastal communities have traded grain for fish for centuries, and this trade still supports local incomes."},{"number":20,"term":"in terms of","sourceTerm":"in terms of","spoken":"in terms of","ipa":"terms /tɝːmz/","type":"word / phrase","meaning":"về mặt, về khía cạnh…","definition":"When considering a particular feature, subject, or point of view.","note":"In terms of + danh từ/cụm danh từ. Không dùng để nối trực tiếp với một mệnh đề hoàn chỉnh.","example":"In terms of nutrition, fresh food is often better than highly processed food."},{"number":21,"term":"initial · initially ~ first · firstly","sourceTerm":"initial · initially ~ first · firstly","spoken":"initial , initially , first , firstly","ipa":"initial /ˌɪˈnɪʃəl/ · initially /ˌɪˈnɪʃəli/ · first /fɝːst/ · firstly /ˈfɝːstli/","type":"adjective · adjective · adverb · adverb · adverb","meaning":"ban đầu (tính từ) · lúc đầu (trạng từ) ~ đầu tiên, thứ nhất · thứ nhất (mở đầu luận điểm)","definition":"Initial and initially refer to the beginning; first marks order, while firstly introduces the first point.","note":"Initial/initially mang nghĩa ban đầu. First chỉ thứ tự đầu tiên. Firstly mở đầu ý thứ nhất trong một danh sách lập luận.","example":"The initial trial produced weak results; initially, the team checked soil quality, and first they measured water levels."},{"number":22,"term":"contain ~ consist of","sourceTerm":"contain ~ consist of","spoken":"contain , consist of","ipa":"contain /kəˈnteɪn/ · consist /kəˈnsɪst/","type":"verb · verb","meaning":"chứa, có bên trong ~ gồm có, được cấu thành từ","definition":"Contain means to have something inside; consist of introduces all the parts that form a whole.","note":"A contains B. A consists of B. Không dùng consist of ở thể bị động.","example":"The meal contains enough protein and consists of beans, rice, and vegetables."},{"number":23,"term":"exist","sourceTerm":"exist (v)","spoken":"exist","ipa":"exist /ɪˈɡzɪst/","type":"verb","meaning":"tồn tại","definition":"To be real, present, or found in a particular place or situation.","note":"","example":"Several traditional varieties still exist in remote farming communities."},{"number":24,"term":"remain","sourceTerm":"remain (v)","spoken":"remain","ipa":"remain /rɪˈmeɪn/","type":"verb","meaning":"vẫn còn, vẫn cứ…","definition":"To continue to exist or stay in the same state after other things have changed.","note":"Remain + tính từ/danh từ. Remain không nhấn mạnh hành động mà nhấn mạnh trạng thái tiếp tục.","example":"Although food prices fell slightly, access to fresh produce remained unequal."},{"number":25,"term":"extent · the extent of sth","sourceTerm":"extent · the extent of sth","spoken":"extent , the extent of something","ipa":"extent /ɪˈkstɛnt/","type":"noun · noun · phrase / pattern","meaning":"mức độ; phạm vi · mức độ hoặc phạm vi của điều gì","definition":"The degree, size, or range of something.","note":"To some/a large extent chỉ một mức độ nào đó hoặc mức độ lớn. The extent of + danh từ.","example":"Satellite images revealed the full extent of the crop damage."},{"number":26,"term":"a range of # a lot of","sourceTerm":"a range of # a lot of","spoken":"a range of , a lot of","ipa":"range /reɪndʒ/ · lot /lɑːt/","type":"noun · noun","meaning":"nhiều loại, một loạt · nhiều, rất nhiều","definition":"A range of emphasizes variety; a lot of emphasizes a large quantity or number.","note":"A range of không chỉ là nhiều mà còn gợi nhiều loại khác nhau.","example":"The market offers a range of local vegetables and a lot of fresh fruit."},{"number":27,"term":"permanent >< temporary","sourceTerm":"permanent >< temporary","spoken":"permanent , temporary","ipa":"permanent /ˈpɝːmənənt/ · temporary /ˈtɛmpɚˌɛri/","type":"adjective · adjective","meaning":"lâu dài, vĩnh viễn · tạm thời","definition":"Permanent is intended to last for a long time; temporary lasts for only a limited period.","note":"Permanent chỉ điều lâu dài hoặc không dự kiến thay đổi. Temporary chỉ điều tạm thời.","example":"The charity sought a permanent solution rather than a temporary supply of food aid."},{"number":28,"term":"crisis","sourceTerm":"crisis (n)","spoken":"crisis","ipa":"crisis /ˈkraɪsəs/","type":"noun","meaning":"cuộc khủng hoảng","definition":"A dangerous or difficult situation that requires urgent action.","note":"Crisis có số nhiều là crises.","example":"The government released emergency grain supplies during the food crisis."},{"number":29,"term":"found · founder · foundation # find","sourceTerm":"found · founder · foundation # find","spoken":"found , founder , foundation , find","ipa":"found /faʊnd/ · founder /ˈfaʊndɚ/ · foundation /faʊˈndeɪʃən/ · find /faɪnd/","type":"verb · verb · noun · noun","meaning":"thành lập, sáng lập · người sáng lập · sự thành lập; nền tảng · tìm thấy","definition":"To found is to establish an organization; a founder establishes it, and its foundation is the act or basis of establishing it.","note":"Found – founded – founded mang nghĩa thành lập. Find – found – found mang nghĩa tìm thấy. Hai động từ khác nhau.","example":"A nutrition scientist founded the organization; as its founder, she established a strong foundation for future research."},{"number":30,"term":"infer · inference # imply","sourceTerm":"infer · inference # imply","spoken":"infer , inference , imply","ipa":"infer /ˌɪˈnfɝː/ · inference /ˈɪnfɚəns/ · imply /ˌɪˈmplaɪ/","type":"verb · verb · noun","meaning":"suy ra · sự suy luận; kết luận được suy ra · ngụ ý, hàm ý","definition":"To infer is to reach a conclusion from evidence; an inference is that conclusion, while imply means to suggest something indirectly.","note":"Infer là điều người đọc hoặc nghiên cứu viên suy ra. Imply là điều người nói hoặc văn bản ngụ ý.","example":"The empty storage rooms implied a shortage, so investigators inferred that supplies had run out; this inference was later confirmed."},{"number":31,"term":"gist ~ main idea","sourceTerm":"gist (n) ~ main idea (n)","spoken":"gist , main idea","ipa":"gist /dʒɪst/ · main /meɪn/ · idea /aɪˈdiːə/","type":"noun · noun","meaning":"ý chính, nội dung cốt lõi","definition":"The central meaning or most important point of a text or discussion.","note":"Get the gist of mang nghĩa nắm được ý chính. Gist thường không dùng cho một chi tiết riêng lẻ.","example":"Even without every statistic, readers can understand the gist of the report."},{"number":32,"term":"very + noun","sourceTerm":"very (a) + noun","spoken":"very + noun","ipa":"very /ˈvɛri/ · noun /naʊn/","type":"adjective · phrase / pattern","meaning":"đứng trước danh từ để nhấn mạnh chính xác người hoặc vật được nói đến","definition":"Used before a noun to emphasize that it is the exact person, thing, place, or time meant.","note":"Very + danh từ mang nghĩa “chính/đúng ngay”. Cấu trúc này khác very + tính từ/trạng từ mang nghĩa “rất”.","example":"The very seeds once considered useless proved able to survive the drought."},{"number":33,"term":"manufacture · manufacturer","sourceTerm":"manufacture · manufacturer","spoken":"manufacture , manufacturer","ipa":"manufacture /ˌmænjəˈfæktʃɚ/ · manufacturer /ˌmænjəˈfæktʃɚ.ɚ/","type":"verb · noun","meaning":"sản xuất công nghiệp · nhà sản xuất; công ty sản xuất","definition":"To produce goods, usually in a factory and on a large scale; a manufacturer is the company or person that produces them.","note":"Dùng manufacture chủ yếu cho quá trình sản xuất công nghiệp, không dùng cho quá trình cây trồng tự sinh trưởng.","example":"The company manufactures farming equipment and is now the region's largest manufacturer."}],"pronunciationFocus":[{"entryNumber":4,"points":[{"category":"word-stress","note":"culprit nhấn âm đầu"},{"category":"final-sound","note":"culprit kết thúc bằng /t/; không thêm nguyên âm sau âm cuối"}]},{"entryNumber":8,"points":[{"category":"common-error","note":"cereal có ba âm tiết và nhấn âm đầu; wheat có nguyên âm dài /iː/"},{"category":"final-sound","note":"wheat kết thúc bằng /t/"}]},{"entryNumber":18,"points":[{"category":"word-stress","note":"continent nhấn âm đầu; hai âm tiết sau đọc nhẹ"}]},{"entryNumber":20,"points":[{"category":"linking","note":"Đọc liền terms‿of, nối /z/ cuối terms sang nguyên âm đầu của of"}]},{"entryNumber":23,"points":[{"category":"word-stress","note":"exist nhấn âm tiết thứ hai"},{"category":"final-sound","note":"exist kết thúc bằng cụm /st/; không bỏ /t/"}]},{"entryNumber":29,"points":[{"category":"word-stress","note":"found và founder nhấn âm đầu; foundation chuyển trọng âm sang âm tiết chứa /eɪ/"},{"category":"final-sound","note":"found kết thúc bằng cụm /nd/"}]},{"entryNumber":33,"points":[{"category":"word-stress","note":"manufacture và manufacturer đều nhấn vào âm tiết chứa /fæk/"}]}]}};
